import inspect
import unittest

from city_twin.branches import BranchStore

from tests.test_lifetime_churn import diamond_store
from tests.test_lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_wave_forecast_scorecard_regression_wave_forecast_backtests_scorecards_regression_wave_forecast_backtests_scorecards_regression_wave_forecasts_backtests_scorecards_regressions import (
    regressions_kwargs,
)

P = "regression_wave_"
BASELINE_CUTOFFS = P * 4 + "baseline_cutoffs"
BASELINE_SPLITS = P * 4 + "baseline_splits"
MIN_CONSECUTIVE = P * 4 + "min_consecutive_splits"
STREAK_LIMIT = P * 4 + "regression_streak_limit"
MIN_ACTIVE = P * 4 + "min_active_regressions"
WAVE_LIMIT = P * 5 + "limit"

WAVES_NAME = (
    "lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_"
    "wave_forecast_scorecard_regression_wave_forecast_backtests_scorecards_"
    "regression_wave_forecast_backtests_scorecards_regression_wave_forecasts_"
    "backtests_scorecards_regressions_waves"
)
STREAKS_NAME = WAVES_NAME[: -len("waves")] + "streaks"
WAVES = getattr(BranchStore, WAVES_NAME)
STREAKS = getattr(BranchStore, STREAKS_NAME)
BUILDER = getattr(BranchStore, "_build_" + WAVES_NAME + "_result")


def waves_kwargs(store_args, **overrides):
    min_active = overrides.pop(MIN_ACTIVE, 1)
    wave_limit = overrides.pop(WAVE_LIMIT, 50)
    kwargs = regressions_kwargs(store_args, **overrides)
    splits = kwargs.pop(BASELINE_CUTOFFS)
    kwargs[BASELINE_SPLITS] = (splits,)
    kwargs[MIN_CONSECUTIVE] = 1
    kwargs[STREAK_LIMIT] = 50
    kwargs[MIN_ACTIVE] = min_active
    kwargs[WAVE_LIMIT] = wave_limit
    return kwargs


def make_streak(identity, start, end):
    return {
        "identity": identity,
        "start_reference_cutoffs": start,
        "end_reference_cutoffs": end,
        "split_count": end - start + 1,
        "first_regression_cutoff": 0,
        "worst_rate_drop": (1, 2),
    }


class SignatureTests(unittest.TestCase):
    def test_appends_two_params_before_token(self):
        names = list(inspect.signature(WAVES).parameters)
        streak_names = list(inspect.signature(STREAKS).parameters)
        self.assertEqual(
            names, streak_names[:-1] + [MIN_ACTIVE, WAVE_LIMIT, "token"]
        )


class BuilderTests(unittest.TestCase):
    def test_shape_and_key_order(self):
        result = BUILDER((make_streak("A", 1, 2),), (1, 2), 1, 50)
        self.assertEqual(list(result), ["waves", "totals"])
        wave = result["waves"][0]
        self.assertEqual(
            list(wave),
            [
                "start_reference_cutoffs",
                "end_reference_cutoffs",
                "split_count",
                "peak_regressions",
                "points",
            ],
        )
        self.assertEqual(
            list(wave["points"][0]),
            ["reference_cutoffs", "active_count", "identities"],
        )
        self.assertEqual(
            list(result["totals"]),
            ["splits", "identities", "waves", "points", "peak_active"],
        )

    def test_threshold_and_adjacency(self):
        streaks = (
            make_streak("A", 1, 2),
            make_streak("B", 2, 4),
            make_streak("C", 4, 4),
        )
        # positions 1,2,4 requested; 3 unrequested (does not break);
        # position 4 has only B,C active -> below min_active=3? no:
        # pos1: A(1) <2; pos2: A,B (2); pos4: B,C (2) -> wave over 2,4
        result = BUILDER(streaks, (1, 2, 4), 2, 50)
        self.assertEqual(len(result["waves"]), 1)
        wave = result["waves"][0]
        self.assertEqual(wave["start_reference_cutoffs"], 2)
        self.assertEqual(wave["end_reference_cutoffs"], 4)
        self.assertEqual(wave["split_count"], 2)
        self.assertEqual(wave["peak_regressions"], 2)
        self.assertEqual(
            [p["reference_cutoffs"] for p in wave["points"]], [2, 4]
        )
        self.assertEqual(
            result["totals"],
            {
                "splits": 2,
                "identities": 3,
                "waves": 1,
                "points": 2,
                "peak_active": 2,
            },
        )

    def test_below_threshold_requested_position_ends_wave(self):
        streaks = (make_streak("A", 1, 1), make_streak("B", 3, 3))
        result = BUILDER(streaks, (1, 2, 3), 1, 50)
        # position 2 has no active streak -> two waves
        self.assertEqual(len(result["waves"]), 2)
        self.assertEqual(
            [w["start_reference_cutoffs"] for w in result["waves"]], [1, 3]
        )

    def test_wave_limit_raises_without_truncating(self):
        streaks = (make_streak("A", 1, 1), make_streak("B", 3, 3))
        with self.assertRaises(ValueError):
            BUILDER(streaks, (1, 2, 3), 1, 1)

    def test_empty(self):
        result = BUILDER((), (1, 2), 1, 50)
        self.assertEqual(result["waves"], ())
        self.assertEqual(
            result["totals"],
            {
                "splits": 0,
                "identities": 0,
                "waves": 0,
                "points": 0,
                "peak_active": 0,
            },
        )

    def test_no_shared_mutable_state(self):
        streak = make_streak("A", 1, 1)
        result = BUILDER((streak,), (1,), 1, 50)
        self.assertIsNot(result["waves"][0]["points"][0], streak)


class ValidationTests(unittest.TestCase):
    def setUp(self):
        self.store, self.args = diamond_store()

    def call(self, **overrides):
        return self.store and getattr(self.store, WAVES_NAME)(
            **waves_kwargs(self.args, **overrides)
        )

    def test_bool_rejected(self):
        for key in (MIN_ACTIVE, WAVE_LIMIT):
            with self.assertRaises(TypeError, msg=key):
                self.call(**{key: True})

    def test_non_int_rejected(self):
        for key in (MIN_ACTIVE, WAVE_LIMIT):
            for bad in (1.0, "2", None):
                with self.assertRaises(TypeError, msg=(key, bad)):
                    self.call(**{key: bad})

    def test_below_one_rejected(self):
        for key in (MIN_ACTIVE, WAVE_LIMIT):
            for bad in (0, -1):
                with self.assertRaises(ValueError, msg=(key, bad)):
                    self.call(**{key: bad})


class EndToEndTests(unittest.TestCase):
    def test_tokenless_query(self):
        store, args = diamond_store()
        result = getattr(store, WAVES_NAME)(
            **waves_kwargs(args, **{BASELINE_SPLITS: (1, 2)})
        )
        self.assertEqual(list(result), ["waves", "totals"])
        self.assertIsInstance(result["waves"], tuple)
        self.assertEqual(
            list(result["totals"]),
            ["splits", "identities", "waves", "points", "peak_active"],
        )

    def test_consistent_with_streaks(self):
        store, args = diamond_store()
        kwargs = waves_kwargs(args, **{BASELINE_SPLITS: (1, 2)})
        result = getattr(store, WAVES_NAME)(**kwargs)
        streak_kwargs = {
            k: v
            for k, v in kwargs.items()
            if k not in (MIN_ACTIVE, WAVE_LIMIT)
        }
        streaks = getattr(store, STREAKS_NAME)(**streak_kwargs)
        rebuilt = BUILDER(
            streaks["streaks"], (1, 2), 1, 50
        )
        self.assertEqual(result, rebuilt)


if __name__ == "__main__":
    unittest.main()
